sources.base.cod:
type Entity;
type Weighted <: Entity;
type Alternate <: Entity;
data Node { value::i64; }
function rank(x::Entity)::i64 { 1 }
function rank(x::Weighted)::i64 { 2 }
export Node; export Entity; export Weighted; export Alternate; export rank;

sources.weighted.cod:
import "base.cod" Node;
using "base.cod" Weighted;
data Node <: Weighted;
function create(arena::region)::ref<Node> { alloc arena Node(7) }
export create;

sources.alternate.cod:
import "base.cod" Node;
using "base.cod" Alternate;
data Node <: Alternate;
function create(arena::region)::ref<Node> { alloc arena Node(9) }
export create;

results.source:
using symbol "std:io" @print;
using "base.cod" Node;
using "base.cod" rank;
using "weighted.cod" create as weighted;
using "alternate.cod" create as alternate;
symbol @arena::region;
effect @arena <- region(4096u64);
behave @print(rank(deref(weighted(@arena))));

using symbol "std:io" @print;
using "base.cod" Node;
using "base.cod" rank;
using "weighted.cod" create as weighted;
using "alternate.cod" create as alternate;
symbol @arena::region;
effect @arena <- region(4096u64);
symbol @node::ref<Node>;
effect @node <- weighted(@arena);
behave @print(rank(deref(@node)));

using symbol "std:io" @print;
using "base.cod" Node;
using "base.cod" rank;
using "weighted.cod" create as weighted;
using "alternate.cod" create as alternate;
symbol @arena::region;
effect @arena <- region(4096u64);
symbol @node::ref<Node>;
effect @node <- weighted(@arena);
proc @inspect() -> i64 { rank(deref(@node)) }
effect @node <- alternate(@arena);
behave @print(perform @inspect());
behave @print(behave @inspect());
behave @print(rank(deref(@node)));

using symbol "std:io" @print;
using "base.cod" Node;
using "base.cod" rank;
using "weighted.cod" create as weighted;
using "alternate.cod" create as alternate;
symbol @arena::region;
effect @arena <- region(4096u64);
using "base.cod" Weighted;
symbol @node::ref<Node>;
function narrow(x::Weighted)::i64 { 2 }
effect @node <- weighted(@arena);
effect @node <- alternate(@arena);
narrow(deref(@node));

